INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70139, 'spa', 'ser abatido al Hades', 'Uso figurado-profético (2 ocurrencias) que expresa el abatimiento forzoso o descenso al Hades, dirigido a ciudades bajo juicio divino. En Mt 11:23 y Lc 10:15, Jesús declara: ''descenderás hasta el Hades'' respecto a Capernaúm. El movimiento físico de ''bajar'' se funde con la dimensión cósmica del castigo escatológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70148, 'spa', 'caer, gotear', 'Una única ocurrencia en Lc 22:44 que describe el sudor de Jesús ''cayendo'' como gotas de sangre en Getsemaní. El sentido pasa del típico ''descender'' a ''caer'', reflejando el sujeto inusual (sudor en lugar de una persona). El movimiento descendente aquí es de líquido goteando al suelo, extendiendo la semántica espacial del verbo del desplazamiento volitivo al descenso gravitacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70159, 'spa', 'Pendiente o bajada', 'Lucas usa κατάβασις para ubicar con precisión el lugar donde la multitud prorrumpió en alabanza. La bajada del Monte de los Olivos ofrecía una vista espectacular de Jerusalén y el templo, convirtiéndola en el lugar idóneo para la aclamación de Jesús como rey. La precisión geográfica ancla la entrada triunfal en una topografía real, mientras la ubicación misma intensifica el drama del momento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70160, 'spa', 'Fundación, fundamento — fundación o establecimiento, usado exclusivamente en la ', 'Fundación, fundamento — fundación o establecimiento, usado exclusivamente en la frase ''la fundación del mundo'' (καταβολὴ κόσμου) para señalar el momento de la creación como punto de partida de los propósitos eternos de Dios. Diez de las once ocurrencias en el NT llevan este sentido. Jesús habla de cosas ''escondidas desde la fundación del mundo'' (Mt 13:35), y Pablo declara que Dios eligió a los creyentes ''antes de la fundación del mundo'' (Ef 1:4). Las traducciones convergen en fundación, Grundlegung y fondation.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70161, 'spa', 'Depósito de simiente, concepción — el depósito o siembra de simiente, es decir, ', 'Depósito de simiente, concepción — el depósito o siembra de simiente, es decir, la concepción biológica. Se encuentra únicamente en Hebreos 11:11, donde Sara ''recibió poder para el depósito de simiente'' (εἰς καταβολὴν σπέρματος), permitiéndole concebir a pesar de su edad. La metáfora subyacente pasa de poner el fundamento de un edificio a sembrar semilla en la tierra — ambos actos de καταβολή (''echar abajo''). Las traducciones en inglés rinden esto como conception de forma única.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70162, 'spa', 'Privar del premio', 'Pablo emplea καταβραβεύω para advertir contra falsos maestros que actúan como jueces ilegítimos. El español ''privar del premio'' y el alemán ''betrügen'' (engañar) capturan la negación injusta. Los falsos maestros en Colosas promovían visiones místicas, adoración a ángeles y ascetismo severo, insinuando que la fe ordinaria era insuficiente. Pablo rechaza su autoridad: no pueden descalificar a quienes Dios ya ha aprobado en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70163, 'spa', 'Heraldo o proclamador', 'Los filósofos atenienses aplican καταγγελεύς a Pablo, identificándolo como un heraldo religioso. El español ''anunciador'' y el francés ''annoncer'' significan proclamador. Los filósofos escuchan el mensaje de Pablo sobre Jesús y la resurrección (ἀνάστασις) y creen que introduce dos nuevas deidades: Jesús y su consorte Anástasis. El malentendido muestra cuán extraño sonaba el evangelio para oídos griegos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70164, 'spa', 'Proclamar públicamente, anunciar (declarar un mensaje públicamente y con autorid', 'Proclamar públicamente, anunciar (declarar un mensaje públicamente y con autoridad, especialmente el evangelio de la muerte, resurrección y perdón de Cristo. El término se concentra en Hechos y las cartas de Pablo como palabra misionera y litúrgica. En Hechos, los apóstoles proclaman la resurrección (Hch 4:2), la palabra de Dios en las sinagogas de Chipre (Hch 13:5) y el perdón por medio de Jesús (Hch 13:38; 17:3, 13; 26:23). Pablo lo emplea para la proclamación eucarística y la predicación apostólica.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70177, 'spa', 'Risa despreciativa', 'Risa burlona y despectiva dirigida contra alguien. En los tres Sinópticos, los dolientes se ríen con escarnio de Jesús al oír que la niña solo duerme: su afirmación les parece absurda. El imperfecto κατεγέλων indica una burla prolongada que expresa rechazo total de lo dicho, no simple humor sino desprecio que descalifica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70178, 'spa', 'Juicio condenatorio', 'Emitir un veredicto desfavorable o declarar culpable. En Gálatas se aplica a la conducta objetivamente condenable de Pedro al apartarse de los gentiles, contradiciendo el evangelio. En 1 Juan se refiere a la voz acusadora de la conciencia, el corazón que nos señala cuando fallamos. Abarca condena externa e interna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70179, 'spa', 'Quebrar o destrozar', 'Quebrar o romper algo rigido, especialmente huesos o una cana, implicando fractura violenta. En Mt 12:20, la cita isaiana promete que el Mesias no quebrara la cana cascada, resaltando la ternura de quien podria quebrar pero elige no hacerlo. En Jn 19:31-33 describe a los soldados romanos quebrando las piernas de los crucificados para apresurar la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70180, 'spa', 'Llevar abajo, conducir', 'Llevar o conducir a una persona de un lugar a otro, generalmente desde una elevación mayor o de una ciudad a otra. Se usa extensamente en Hechos para la escolta de Pablo: los discípulos lo llevaron a Cesarea (Hch 9:30), el comandante lo hizo bajar al concilio (Hch 22:30) y se pidió al tribuno que lo trajera abajo al Sanedrín (Hch 23:15, 20, 28). Lucas 5:11 lo emplea para llevar las barcas a tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70182, 'spa', 'Atracar, llegar a puerto', 'Término técnico náutico en uso pasivo o intransitivo para un barco que atraca en puerto o llega a la costa. En Hechos 27:3 el barco de Pablo ''atracó en Sidón'' y en Hechos 28:12 ''atracaron en Siracusa''. El español recurre al verbo marítimo especializado ''atracar'', distinguiendo claramente este sentido del significado general de conducir a una persona hacia abajo. La forma pasiva κατήχθημεν (''fuimos llevados abajo'') refleja la perspectiva del pasajero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70188, 'spa', 'Conquistar por fe', 'Hebreos emplea καταγωνίζομαι para celebrar el poder victorioso de la fe. El español ''conquistaron'' y el francés ''surmonter'' (superar) transmiten triunfo. Los héroes de la fe sometieron reinos no por fuerza humana sino confiando en Dios: Gedeón con 300 hombres, David contra Goliat, Josué en Jericó. El verbo demuestra que la fe no es resignación pasiva sino compromiso activo que reconoce la intervención divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70189, 'spa', 'Vendar heridas', 'Lucas usa καταδέω para describir el cuidado directo del samaritano hacia el viajero herido. El español ''vendó'' y el francés ''bander'' significan vendar. El detalle demuestra compasión costosa: el samaritano no solo sintió lástima sino que actuó, proporcionando primeros auxilios, transporte, alojamiento y pago por el cuidado continuo. Jesús cuenta esta parábola para definir ''prójimo'', no por cercanía étnica o geográfica sino por misericordia activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70190, 'spa', 'Manifiesto y evidente', 'La única aparición en el Nuevo Testamento ocurre en un argumento teológico formal donde el autor de Hebreos establece que el cambio de sacerdocio es κατάδηλος: no oculto ni debatible, sino manifiesto para todo aquel que considere la evidencia. El consenso interlingüístico en ''evidente/manifiesto'' confirma que se trata de claridad epistémica, no de mera visibilidad física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70191, 'spa', 'Condenar, sentenciar', 'Pronunciar un veredicto de culpabilidad o dictar sentencia contra alguien, en un proceso legal o en un juicio moral. El prefijo κατα- intensifica δικάζω (juzgar), dando fuerza de fallo adverso decisivo. Jesús lo emplea como advertencia (Mt 12:37) y como exhortación a la misericordia: «no condenéis y no seréis condenados» (Lc 6:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70197, 'spa', 'Búsqueda decidida', 'Simón y sus compañeros emprenden una búsqueda activa y resuelta de Jesús en la madrugada, no una simple indagación casual. La elección del verbo transmite la urgencia y minuciosidad de su esfuerzo: lo rastrearon hasta su lugar de oración, lo cual concuerda con el sentido clásico de seguimiento tenaz e implacable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70200, 'spa', 'Ser avergonzado (pasivo)', 'Ser avergonzado (pasivo): la experiencia pasiva de ser puesto en vergüenza, deshonrado o defraudado en la propia esperanza o confianza. El sujeto es quien sufre o podría sufrir la vergüenza, y el verbo frecuentemente lleva un matiz escatológico: la confianza del creyente en Dios no será finalmente confundida. Pablo cita a Isaías en Ro 9:33 y 10:11 con la promesa «no será avergonzado», y 1 Pe 2:6 hace eco de la misma certeza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70201, 'spa', 'Avergonzar (activo)', 'Avergonzar (activo): la imposición activa de vergüenza sobre alguien — causar deshonra, humillar o confundir. Aquí el sujeto es el agente que avergüenza, y el verbo aparece frecuentemente en contextos de inversión divina donde Dios trastorna las jerarquías humanas de estatus. En 1 Co 1:27 Dios «escogió lo necio para avergonzar a los sabios», y en 1 Co 11:4-5 quien ora con la cabeza impropiamente cubierta «avergüenza su cabeza».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70209, 'spa', 'Ser quemado, consumido por el fuego (pasivo)', 'Ser quemado, consumido por el fuego (pasivo): la experiencia pasiva de ser consumido o destruido por el fuego. En Mt 13:40 la cizaña «es quemada» como imagen del juicio escatológico. Pablo advierte que el constructor cuya obra no resista la prueba sufrirá pérdida al ser «quemada» (1 Co 3:15). Hebreos 13:11 señala que los animales del sacrificio eran «quemados fuera del campamento». Las visiones de fuego cósmico en Apocalipsis — la tercera parte de los árboles quemada (Ap 8:7) — llevan este sentido a escala universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70210, 'spa', 'Quemar, consumir con fuego (activo)', 'Quemar, consumir con fuego (activo): el acto activo y transitivo de prender fuego a algo y quemarlo por completo. Juan el Bautista proclama que el Mesías «quemará la paja con fuego que nunca se apagará» (Mt 3:12; Lc 3:17), y Jesús ordena que la cizaña sea atada y quemada (Mt 13:30). En Hch 19:19 los conversos de Éfeso «quemaron» públicamente sus libros de magia. Apocalipsis 17:16 describe a la bestia y los diez cuernos que «quemarán» a la ramera con fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70218, 'spa', 'Cubrirse la cabeza', 'Cubrirse la cabeza, particularmente en el contexto del culto. El argumento de Pablo en 1 Corintios 11 es notoriamente difícil, involucrando el orden creacional, la gloria, la autoridad y los ángeles. Lo claro es la acción: las mujeres cubriéndose y los varones sin cubrirse. La construcción en voz media sugiere «que se cubra ella misma».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70219, 'spa', 'Jactarse contra otro', 'Jactarse contra otro o gloriarse sobre el, afirmando la propia superioridad o ventaja. Pablo lo usa en Romanos 11:18 para advertir a los cristianos gentiles contra la arrogancia hacia Israel. En Santiago 3:14 advierte contra la jactancia que contradice la verdad. El prefijo κατά le confiere un matiz adversativo que lo distingue de la jactancia comun.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70220, 'spa', 'Yacer, estar postrado en cama', 'Yacer, estar postrado en cama: acostarse físicamente, generalmente por enfermedad, lesión u otra causa que confina al lecho. La suegra de Pedro ''estaba acostada'' con fiebre (Marcos 1:30); el paralítico ''yacía'' sobre una camilla cuando lo trajeron a Jesús (Marcos 2:4); multitudes de enfermos ''yacían'' junto al estanque de Betesda (Juan 5:3, 6). La orden al paralítico sanado de levantarse y tomar su lecho presupone esta postura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70222, 'spa', 'Reclinarse a la mesa', 'Reclinarse a la mesa: adoptar la postura reclinada propia de las comidas en el mundo grecorromano y del Cercano Oriente. En el banquete de Leví, ''muchos publicanos y pecadores estaban reclinados a la mesa con Jesús'' (Marcos 2:15). En casa de Simón el leproso, Jesús ''estaba reclinado a la mesa'' cuando una mujer lo ungió (Marcos 14:3). Pablo plantea si alguien con conciencia débil podría ver a otro ''reclinado a la mesa'' en un templo de ídolos (1 Corintios 8:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70233, 'spa', 'Herencia territorial divina', 'En su sermón en Antioquía de Pisidia, Pablo relata cómo Dios, tras destruir siete naciones en Canaán, distribuyó sus tierras a Israel como herencia: una transferencia formal de posesión territorial orquestada por Dios. El término evoca las ceremonias de sorteo descritas en Josué, donde los límites tribales se establecieron mediante proceso sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70234, 'spa', 'Reclinarse a la mesa', 'Hacer reclinarse o reclinarse a la mesa para comer, reflejando la costumbre grecorromana de reclinarse en los banquetes. Usado exclusivamente en Lucas: Jesus reclinandose en la cena de un fariseo (Lucas 7:36), dirigiendo a la multitud a sentarse en grupos antes de la alimentacion de los cinco mil (Lucas 9:14-15), ensenando sobre la humildad en los banquetes tomando el lugar mas bajo (Lucas 14:8), y reclinandose con los discipulos en Emaus (Lucas 24:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70235, 'spa', 'Diluvio destructor', 'El argumento de Pedro sobre la continuidad del juicio divino recuerda el κατακλυσμός primordial, cuando el cosmos antiguo «fue inundado» y pereció. El participio pasivo perfecto indica acción completada con resultado permanente: el mundo sufrió una sumersión total. Esto ancla la expectativa escatológica en el precedente histórico de la intervención divina mediante catástrofe natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70236, 'spa', 'Diluvio de Noe', 'Un gran diluvio o inundacion catastrofica, usado en el NT exclusivamente para el diluvio de Noe como acto paradigmatico de juicio divino. Las cuatro apariciones remiten al relato del Genesis: Jesus lo emplea como tipo de los ultimos tiempos (Mateo 24:38-39; Lucas 17:27), y Pedro lo invoca para demostrar la disposicion de Dios a juzgar a los malvados mientras preserva a los justos (2 Pedro 2:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70238, 'spa', 'Autolesión compulsiva', 'La autolesión compulsiva del hombre poseído con piedras manifiesta el tormento demoníaco que lo dominaba: se «cortaba» repetidamente, incapaz de detener la conducta destructiva. Este detalle vívido establece la gravedad de su estado antes de la intervención de Jesús. Las asociaciones clásicas del verbo con el desmembramiento violento subrayan la brutalidad del daño autoinfligido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70239, 'spa', 'Despeñar con violencia', 'La muchedumbre enfurecida de la sinagoga llevó a Jesús hasta un precipicio con la intención expresa de «despeñarlo», no simplemente de expulsarlo, sino de ejecutarlo arrojándolo por el despeñadero. La precisión del verbo indica una acción violenta premeditada, aunque Jesús pasa misteriosamente por en medio de ellos. Esto prefigura los posteriores rechazos y conspiraciones asesinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70240, 'spa', 'Veredicto condenatorio', 'El veredicto que declara culpable y sentencia en consecuencia. En Romanos 5:16 se opone directamente a la justificación (δικαίωμα): condenación frente a absolución. El paralelismo de 5:18 presenta la condenación como resultado universal de la transgresión de Adán, respondida por la justificación en Cristo. Romanos 8:1 celebra la liberación total de ese veredicto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70241, 'spa', 'Condenar, dictar sentencia en contra (pronunciar un veredicto formal de culpabil', 'Condenar, dictar sentencia en contra (pronunciar un veredicto formal de culpabilidad y sentencia contra alguien, ya sea en tribunales humanos o en el juicio divino. Los relatos de la pasión lo usan para la sentencia de muerte del Sanedrín contra Jesús (Mt 20:18; Mc 10:33; 14:64; Mt 27:3). Jesús mismo advierte que Nínive y la reina del Sur condenarán a la generación presente por contraste en el día final (Mt 12:41-42; Lc 11:31-32). El uso teológico de Pablo declara que Dios condenó al pecado en la carne mediante su Hijo (Ro 8:3).)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70253, 'spa', 'Ensenorearse, dominar', 'Ejercer autoridad opresiva o dominante sobre otros, ensenoreandose de ellos. Jesus lo usa negativamente respecto a los gobernantes gentiles (Mateo 20:25; Marcos 10:42), y Pedro advierte a los ancianos de la iglesia contra la misma actitud (1 Pedro 5:3). En Hechos 19:16 el verbo pasa al sometimiento fisico cuando un endemoniado domina a sus atacantes, mostrando la fuerza cruda que encierra el termino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70254, 'spa', 'Calumniar, difamar', 'Hablar en contra de alguien, calumniar o difamar con palabras hostiles o maliciosas. Santiago 4:11 acumula tres formas de esta palabra para mostrar cuan extendido esta este pecado entre los creyentes, mientras Pedro la emplea para describir como los no creyentes maldicen a los cristianos (1 Pedro 2:12; 3:16). El termino implica un ataque verbal contra el caracter de una persona, condenado como transgresion de la ley del amor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70256, 'spa', 'Calumniador habitual', 'En el catálogo paulino de la depravación humana, los «calumniadores» aparecen junto a los aborrecedores de Dios e inventores de maldad: personas cuyo discurso destruye sistemáticamente a otros mediante informes falsos o malintencionados. El término no se refiere a un chisme ocasional, sino a personas definidas por su comunicación difamatoria. Este vicio destruye la comunidad mediante el uso de la palabra como arma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70257, 'spa', 'Sorprender en el acto', 'Sorprender en el acto: un sentido forense o judicial que denota atrapar a alguien con las manos en la masa. Tanto Juan 8:3 como 8:4 usan el participio pasivo: la mujer ''habiendo sido sorprendida'' en adulterio. El español ''sorprendida'' y el tiempo perfecto enfatizan la naturaleza consumada e innegable de la aprehensión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70258, 'spa', 'Alcanzar o sobrevenir', 'Alcanzar o sobrevenir: se usa de la oscuridad, la calamidad o una fuerza perseguidora que alcanza a alguien. En Juan 1:5 las tinieblas ni ''alcanzaron'' ni ''vencieron'' a la luz; la ambigüedad del griego es deliberada. Marcos 9:18 lo emplea para un espíritu que se apodera de un muchacho. El español ''agarrar/alcanzar'' capta tanto la presa física como la idea de dar alcance.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70260, 'spa', 'Comprender o percibir mentalmente', 'Comprender o percibir mentalmente: una metáfora cognitiva de lo que la mente ''capta''. Pedro comprende (καταλαμβάνω) que Dios no hace acepción de personas (Hechos 10:34); Pablo ora para que los creyentes comprendan la anchura y profundidad del amor de Cristo (Efesios 3:18). En francés y alemán ''saisir/ergreifen'' reflejan el mismo puente de lo físico a lo mental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70262, 'spa', 'Asir o alcanzar una meta', 'Asir o alcanzar una meta: el sentido atlético y espiritual de esforzarse por agarrar un premio. Pablo confiesa que aún no lo ha ''alcanzado'' pero prosigue adelante (Filipenses 3:12-13). Los gentiles paradójicamente ''alcanzaron'' una justicia que no buscaban (Romanos 9:30). El español ''alcanzar'' se alinea perfectamente con este sentido de búsqueda esforzada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70263, 'spa', 'Ser asido o aprehendido por otro', 'Ser asido o aprehendido por otro: el pasivo divino. Pablo declara que fue ''alcanzado'' por Cristo Jesús (Filipenses 3:12). No se trata de esfuerzo propio, sino de ser agarrado desde fuera. El español ''fui alcanzado'' transmite la inversión: el perseguidor se convierte en perseguido, asido por la gracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70271, 'spa', 'Inscripción oficial', 'La instrucción pastoral establece criterios para determinar qué viudas deben «ser inscritas», es decir, registradas oficialmente para recibir el apoyo continuo de la iglesia. El imperativo pasivo sugiere una decisión comunitaria y un proceso formal, no una caridad improvisada. Esto implica la existencia de una lista organizada mantenida por la iglesia para el cuidado sistemático de las viudas que cumplían los requisitos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70272, 'spa', 'Dejar atrás o partir de una persona, lugar o situación', 'Dejar atrás o partir de una persona, lugar o situación: el sentido activo dominante que cubre la mayoría de las apariciones neotestamentarias. Jesús deja Nazaret (Mateo 4:13), parte de una generación (Mateo 16:4) y se va de Betania (Mateo 21:17). La fórmula matrimonial del Génesis — el hombre dejará padre y madre — aparece mediante este verbo (Mateo 19:5; Marcos 10:7; Efesios 5:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70275, 'spa', 'En voz pasiva, quedar atrás, permanecer como residuo o remanente después de que ', 'En voz pasiva, quedar atrás, permanecer como residuo o remanente después de que otros se han ido. Los acusadores de la mujer sorprendida en adulterio se retiran uno a uno hasta que Jesús queda solo con ella (Juan 8:9); Pablo y Silas se describen como dejados en Atenas (1 Tesalonicenses 3:1). Hebreos 4:1 advierte que no quede vigente una promesa de entrar en el reposo de Dios mientras algunos no la alcanzan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70284, 'spa', 'Reservar o apartar para un propósito determinado', 'Reservar o apartar para un propósito determinado: un sentido poco frecuente pero teológicamente relevante en Romanos 11:4, donde Dios declara: Reservé para mí siete mil hombres que no han doblado la rodilla ante Baal. Aquí καταλείπω va más allá del mero dejar espacial hacia la intencionalidad divina: Dios guarda activamente un remanente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70285, 'spa', 'Lapidación por turba', 'Las autoridades religiosas reconocen que desacreditar públicamente a Juan el Bautista provocaría que la multitud los apedreara, no una simple desaprobación sino violencia letal. Su temor a ser καταλιθάσει (apedreados) motiva su respuesta evasiva a Jesús. Esto revela tanto la reverencia del pueblo por Juan como la cobardía de los líderes ante la convicción popular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70286, 'spa', 'Reconciliacion divina', 'La restauracion de la relacion entre Dios y la humanidad pecadora, lograda mediante la obra expiatoria de Cristo. Pablo desarrolla este concepto plenamente en Romanos 5:11 y 2 Corintios 5:18-19, enfatizando que Dios es el agente iniciador que reconcilia al mundo consigo mismo. En Romanos 11:15, el termino adquiere una dimension historico-salvifica: el endurecimiento temporal de Israel ha significado reconciliacion para las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70287, 'spa', 'Reconciliar, restaurar', 'Pasar de un estado de enemistad a uno de amistad y relación restaurada. En el NT se convierte en término teológico fundamental: Dios reconcilió al mundo consigo mismo en Cristo (2 Co 5:18-19), los creyentes fueron reconciliados siendo aún enemigos (Ro 5:10), y Pablo aplica el mismo verbo a la reconciliación conyugal (1 Co 7:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70293, 'spa', 'Remanente de la humanidad', 'Santiago aplica la profecía de Amós sobre «el resto de los hombres» a la misión gentil, argumentando que su inclusión cumple las Escrituras en lugar de violarlas. El adjetivo κατάλοιποι designa a los que quedan después del juicio o la separación; aquí, las naciones más allá de Israel que sin embargo buscan a Dios. Esta teología del remanente se expande para abarcar a toda la humanidad que invoca el nombre del Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70294, 'spa', 'Alojamiento temporal', 'Hospedaje temporal, ya sea posada pública o aposento privado para huéspedes. En Lucas 2:7 la falta de lugar en el mesón enmarca el humilde nacimiento de Jesús. En Marcos 14:14 y Lucas 22:11, el κατάλυμα es el aposento alto preparado para maestros visitantes y sus discípulos, donde Jesús compartió su última Pascua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70295, 'spa', 'Derribar, demoler (el sentido físico central', 'Derribar, demoler (el sentido físico central: desmontar, desmantelar o demoler una estructura en pie. Jesús habla de las piedras del Templo que serán derribadas de modo que no quede piedra sobre piedra (Mt 24:2; Mc 13:2). La acusación en su juicio repite el cargo (Mt 26:61, Mc 14:58). En cada caso el objeto es un edificio o monumento.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70296, 'spa', 'Abolir, anular (extensión figurada al ámbito legal e institucional', 'Abolir, anular (extensión figurada al ámbito legal e institucional: abolir, anular o derrocar leyes, profecías o planes divinamente ordenados. Jesús aclara que no vino a abolir sino a cumplir la Ley y los Profetas (Mt 5:17). Gamaliel advierte al Sanedrín que una obra de Dios no puede ser derrocada (Hch 5:38-39).)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70298, 'spa', 'Hospedarse, alojarse (un sentido enteramente distinto, arraigado en la imagen de', 'Hospedarse, alojarse (un sentido enteramente distinto, arraigado en la imagen de desuncir a los animales de carga al final de la jornada: detenerse, alojarse o encontrar hospedaje como huésped. Cuando los Doce instan a Jesús a despedir a la multitud para que se alojen en las aldeas cercanas (Lc 9:12), y cuando los observadores murmuran que Jesús ha ido a hospedarse con Zaqueo (Lc 19:7), la palabra transmite calidez y hospitalidad.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70308, 'spa', 'Observación contemplativa', 'Jesús instruye a sus discípulos ansiosos a «observar detenidamente» cómo crecen las flores silvestres sin trabajar ni hilar, y sin embargo superan el esplendor de Salomón. El verbo compuesto sugiere no un simple vistazo casual sino un examen sostenido y reflexivo: aprender de la naturaleza sobre la provisión divina. Esta observación contemplativa produce una comprensión teológica que calma la inquietud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70309, 'spa', 'Testimonio legal adverso', 'El sentido es el de testimonio legal contra un acusado. Los tres usos aparecen en los juicios de Jesús —ante el Sanedrín y ante Pilato— donde testigos o acusadores «testifican en contra» de él. Tanto el sumo sacerdote como Pilato expresan asombro ante el silencio de Jesús a pesar del testimonio acumulado. El imperfecto (καταμαρτυροῦσιν) en Mateo 27:13 sugiere un testificar continuo y reiterado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70310, 'spa', 'Permanecer en un lugar', 'Los once apóstoles (con sus nombres enumerados) ''permanecían'' en el aposento alto de Jerusalén, manteniendo presencia continua mientras aguardaban la promesa. El participio indica que ese era su lugar establecido para la oración y la comunión durante el intervalo entre la ascensión y Pentecostés. Su persistencia en el lugar manifiesta una expectación obediente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70311, 'spa', 'Maldición divina', 'La visión de Juan del cosmos renovado promete la ausencia total de κατανάθεμα: ninguna cosa maldita, ningún objeto de juicio divino, ninguna separación de la presencia de Dios. Esto revierte la maldición de Génesis 3 y todas sus consecuencias. La negación enfática señala restauración completa donde nada lleva la marca de destrucción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70312, 'spa', 'Proferir maldiciones', 'En su tercera negación, Pedro no solo juró sino que comenzó ''a maldecir'', invocando imprecaciones sobre sí mismo o maldiciendo a Jesús para probar que no lo conocía. Esta violencia verbal revela su terror y apostasía momentánea. El infinitivo sugiere que estaba maldiciendo cuando cantó el gallo, deteniendo su caída en espiral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70313, 'spa', 'Fuego consumidor', 'El autor caracteriza a Dios como ''fuego consumidor'', no como quien consumió en el pasado, sino como aquel cuya naturaleza misma es devorar todo lo impío. El participio presente enfatiza una actividad continua y esencial, no actos aislados. Este retrato imponente fundamenta la exhortación a adorar con reverencia y temor, reconociendo la santidad divina que purifica mediante el fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70314, 'spa', 'Carga económica', 'El sentido es el de ser una carga financiera o material para alguien. El triple uso de Pablo establece su patrón: a pesar de tener derecho apostólico al sustento material, eligió no gravar a los corintios. El verbo evoca la idea de presionar hacia abajo, de abrumar con demandas o necesidades. En 12:14 explica su lógica: los padres proveen para los hijos, no al revés; él es su padre espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70315, 'spa', 'Hacer señas urgentes', 'La tripulación de Simón, luchando con redes que se rompían por la carga de peces, ''hizo señas'' a sus compañeros: no había tiempo para gritar, solo gestos urgentes pidiendo ayuda. El aoristo sugiere un llamado rápido y decisivo en medio de la pesca. Esta comunicación sin palabras transmite la abundancia y la necesidad práctica, preparando el asombro ante Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70316, 'spa', 'Considerar, observar atentamente', 'Considerar, observar atentamente: dirigir la atención cuidadosamente hacia un objeto, persona o situación, examinándolo con enfoque sostenido y reflexión. Se usa en contextos variados: desde el desafío de Jesús de considerar la viga en el propio ojo (Mateo 7:3) hasta la invitación a observar los lirios (Lucas 12:27). En Hechos 7:31 Moisés se acerca a la zarza ardiente ''para contemplarla'', y en Hebreos 3:1 se exhorta a los creyentes a considerar al apóstol y sumo sacerdote de nuestra confesión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70324, 'spa', 'Percibir, discernir', 'Percibir, discernir: percibir o discernir la verdadera naturaleza de una situación, obteniendo una comprensión que va más allá de la observación superficial. Se emplea solo en Lucas 20:23, donde Jesús percibió la astucia de quienes intentaban atraparlo con una pregunta sobre el tributo al César. El español ''habiendo percibido'' marca el paso de la observación cuidadosa a la comprensión penetrante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70327, 'spa', 'Llegar, arribar a un lugar', 'Llegar, arribar a un lugar: llegada física a un destino geográfico, alcanzar una ciudad, región o puerto mediante un viaje. Este es el uso predominante en Hechos, donde estructura los viajes misioneros de Pablo: llegar a Derbe y Listra (Hechos 16:1), Éfeso (Hechos 18:19, 18:24), Mileto pasando por Asón (Hechos 20:15) y Tolemaida (Hechos 21:7). Las traducciones son consistentemente espaciales y concretas: ''Llegaron/Llegó'' en español.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70331, 'spa', 'Alcanzar, lograr una meta o estado', 'Alcanzar, lograr una meta o estado: logro figurado de una meta, estado o condición espiritual, alcanzar algo no espacial mediante el esfuerzo, el crecimiento o la acción divina. Pablo lo emplea para la aspiración de ''alcanzar la resurrección de entre los muertos'' (Filipenses 3:11) y el llamado de la iglesia a ''llegar a la unidad de la fe y a la medida de la estatura de Cristo'' (Efesios 4:13). En Hechos 26:7 las doce tribus de Israel sirven a Dios esperando ''alcanzar'' la promesa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70336, 'spa', 'Estupor espiritual judicial', 'Pablo cita a los profetas para explicar cómo Dios dio a Israel «un espíritu de κατάνυξις», no iluminación sino estupefacción, un endurecimiento judicial que hizo ciegos los ojos y sordos los oídos. Este entumecimiento inducido por el Espíritu explica la resistencia de Israel ante el Mesías. El estupor es la respuesta divina al rechazo persistente, aunque Pablo argumenta que es temporal y sirve a propósitos redentores mayores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70337, 'spa', 'Compunción del corazón', 'La acusación de Pedro de que «vosotros crucificasteis» al Señor traspasó a sus oyentes: «fueron punzados en el corazón», experimentando una convicción súbita y dolorosa. El aoristo pasivo sugiere una respuesta involuntaria a la verdad, no una persuasión gradual. Esta herida metafórica de la conciencia, obrada por el Espíritu mediante la palabra, produce arrepentimiento inmediato y el clamor por remedio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70338, 'spa', 'Dignidad ante Dios', 'El sentido es ser juzgado o considerado digno, particularmente según la estimación de Dios. Lucas 20:35 habla de la dignidad para la resurrección: aquellos a quienes Dios juzga aptos para el siglo venidero. Hechos 5:41 presenta el sufrimiento por Jesús como un honor: los apóstoles fueron considerados dignos de ese privilegio. 2 Tesalonicenses 1:5 conecta la perseverancia bajo persecución con la dignidad para el reino de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70339, 'spa', 'Pisotear, hollar', 'Pisar o aplastar con los pies, literal o metafóricamente. En sentido literal: semilla aplastada en el camino (Lc 8:5) y sal pisada por transeúntes (Mt 5:13). En sentido figurado denota trato despectivo: Mateo 7:6 advierte contra entregar lo santo a quienes lo pisotearán, y Hebreos 10:29 describe la apostasía como pisotear al Hijo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70340, 'spa', 'Reposo divino prometido', 'Un estado o lugar de descanso, específicamente el reposo prometido por Dios — la cesación del trabajo que comenzó en la creación y permanece disponible para los fieles. En Hebreos 3-4, el autor desarrolla katapausis como un concepto teológico que abarca la creación, la generación del desierto y la era presente: Dios reposó de sus obras (He 4:4), los israelitas desobedientes no lograron entrar en ese reposo (He 3:11), y la promesa sigue vigente para el pueblo de Dios hoy.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70341, 'spa', 'Cesar, refrenar o reposar', 'Detener o impedir una acción (transitivo), o descansar y cesar del trabajo (intransitivo). En Hechos 14:18, Pablo y Bernabé luchan por contener a la multitud de Listra. En Hebreos 4:4, 8 y 10 predomina el sentido intransitivo: Dios reposó de la creación, Josué no logró dar reposo duradero, y el creyente cesa de sus propias obras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70342, 'spa', 'Cortina o velo', 'La cortina o velo del Templo, específicamente el velo interior que separaba el Lugar Santo del Lugar Santísimo donde moraba la presencia de Dios. Los relatos sinópticos de la crucifixión registran que se rasgó de arriba abajo (Mt 27:51; Mr 15:38; Lc 23:45), significando el acceso libre a Dios. Hebreos interpreta esto tipológicamente: Jesús como precursor entra a la presencia divina a nuestro favor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70344, 'spa', 'Tragar, devorar, abrumar', 'Tragar, devorar o engullir por completo, ya sea consumiendo literalmente o abrumando y destruyendo figuradamente. La palabra transmite la fuerza de una absorción total. Jesús la usa con humor para tragarse un camello (Mt 23:24). Pablo la transforma en grito de victoria: la muerte tragada (1 Co 15:54) y lo mortal absorbido por la vida (2 Co 5:4). También puede significar ser abrumado por una tristeza excesiva (2 Co 2:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70350, 'spa', 'Caída hacia abajo', 'El sentido es caer de una posición superior a una inferior, ya se trate de semillas, personas derribadas o un colapso anticipado. La semilla de la parábola «cayó» en diversos suelos: movimiento pasivo descendente. Pablo y sus compañeros «cayeron a tierra» ante el Cristo resucitado, derribados por un encuentro divino. Los malteses esperaban que Pablo «cayera» muerto por la mordedura de serpiente. El participio aoristo (καταπεσόντων) subraya la acción puntual de la caída.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70351, 'spa', 'Arribo por navegación', 'Tras calmar la tempestad, Jesús y los discípulos «navegaron y llegaron» a la tierra de los gadarenos. El verbo marca la finalización exitosa del viaje tormentoso: alcanzaron la orilla a pesar de la tormenta. Esta llegada a territorio gentil prepara la escena para el dramático exorcismo y la destrucción de los cerdos, demostrando la autoridad de Jesús incluso en regiones paganas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70354, 'spa', 'Maldición', 'Una maldición: pronunciamiento que invoca daño, desgracia o juicio divino sobre una persona o cosa. El prefijo κατα- (sobre, contra) intensifica la raíz ἀρά (imprecación), dando el sentido de invocar destrucción. El uso de Pablo en Gálatas 3:10-13 es teológicamente fundamental: la maldición de la ley recae sobre todo el que no la cumple perfectamente, y Cristo absorbe esa maldición en redención sustitutoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70356, 'spa', 'Maldecir, imprecar', 'Pronunciar una maldición sobre alguien, invocar el mal o el juicio divino contra otra persona. La forma en voz media (καταράομαι) sugiere el acto de invocar maldiciones como un acto de habla dirigido contra otro. En el NT aparece en los mandamientos éticos de Jesús y Pablo de bendecir en vez de maldecir (Mt 5:44; Lc 6:28; Ro 12:14), en la maldición de Jesús a la higuera infructuosa (Mr 11:21), y en el juicio escatológico (Mt 25:41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70361, 'spa', 'Abolir, poner fin, dejar sin efecto', 'Abolir, poner fin, dejar sin efecto: el sentido paulino dominante con 16 apariciones. Algo que antes tenía fuerza o autoridad queda ahora inoperante u obsoleto. En 1 Corintios 13:8-10 la profecía y el conocimiento serán abolidos cuando venga lo perfecto; en 2 Corintios 3:7-14 la gloria del antiguo pacto está siendo abolida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70363, 'spa', 'Anular o invalidar una pretensión legal o promisoria, con 5 apariciones todas en', 'Anular o invalidar una pretensión legal o promisoria, con 5 apariciones todas en Romanos y 1 Corintios. Las preguntas retóricas urgentes de Pablo impulsan este sentido: ¿Anulamos entonces la ley por la fe? (Romanos 3:31); ¿Acaso ha sido anulada la fidelidad de Dios? (Romanos 3:3). Lucas 13:7 extiende el uso a la higuera estéril que inutiliza la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70366, 'spa', 'Destruir, aniquilar un poder adversario, con 3 apariciones donde la fuerza va má', 'Destruir, aniquilar un poder adversario, con 3 apariciones donde la fuerza va más allá del mero cese hacia un derrocamiento activo y violento. Cristo destruirá al que tiene el poder de la muerte, el diablo (Hebreos 2:14); el inicuo será destruido en la venida de Cristo (2 Tesalonicenses 2:8); incluso el estómago y la comida los destruirá Dios (1 Corintios 6:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70374, 'spa', 'Liberar o soltar de una obligación vinculante, con 2 apariciones ambas en Romano', 'Liberar o soltar de una obligación vinculante, con 2 apariciones ambas en Romanos 7. La mujer casada ha sido liberada de la ley de su marido al morir este (Romanos 7:2); los creyentes fueron liberados de la ley, habiendo muerto a lo que los ataba (Romanos 7:6). La voz pasiva enfatiza la libertad recibida, no la acción propia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70381, 'spa', 'Separar o apartar de una relación', 'Separar o apartar de una relación: una única aparición notable en Gálatas 5:4, donde Pablo advierte: De Cristo os desligasteis, los que por la ley os justificáis. El griego aquí es marcadamente personal y relacional: no se anula una ley o institución, sino que se rompe un vínculo vivo con Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70385, 'spa', 'Inclusión oficial numerada', 'Pedro señala que Judas «fue contado entre nosotros»: había sido formalmente incluido como uno de los doce apóstoles, no un allegado sino un miembro pleno. El participio perfecto subraya el hecho establecido de su pertenencia, haciendo su traición aún más impactante. Este reconocimiento establece la vacante que debe llenarse para restaurar la plenitud de los Doce.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70386, 'spa', 'Remendar, reparar, restaurar', 'Remendar, reparar, restaurar: reparar algo físicamente roto o restaurar a una persona que ha caído. En Mateo 4:21 y Marcos 1:19 los discípulos están remendando (καταρτίζοντας) sus redes, una imagen concreta y tangible. Pablo extiende esto a Gálatas 6:1, donde los espirituales deben ''restaurar'' con mansedumbre al hermano sorprendido en falta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70387, 'spa', 'Preparar, disponer', 'Preparar, disponer: preparar o disponer para un propósito divinamente asignado. En Hebreos 10:5 un cuerpo fue ''preparado'' para Cristo; en Romanos 9:22 hay vasos ''preparados para destrucción''. El énfasis recae en la disposición previa: algo hecho apto antes del momento de su uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70389, 'spa', 'Completar, perfeccionar, equipar', 'Completar, perfeccionar, equipar: llevar a plenitud, equipar cabalmente o perfeccionar, referido a la obra de Dios en la maduración de los creyentes o al llamado a estar unidos en un mismo sentir. La oración de Pablo en 1 Tesalonicenses 3:10 pide a Dios que ''complete'' lo que falta en la fe. Lucas 6:40 dice que el discípulo completamente preparado será como su maestro, empleando el participio κατηρτισμένος.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70392, 'spa', 'Formar, constituir, crear', 'Formar, constituir, crear: formar o constituir algo trayéndolo a la existencia, usado de manera única en Hebreos 11:3 sobre Dios que constituyó el mundo visible por su palabra. Los siglos mismos fueron ''constituidos'' de modo que lo visible no fue hecho de lo que se ve.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70398, 'spa', 'Restauración y perfección', 'Pablo se goza cuando él es débil pero los corintios son fuertes, y ora por su κατάρτισις, su completa restauración o perfección. Esto puede significar sanar divisiones, completar su formación espiritual o restaurarlos plenamente tras su necesaria reprensión. El término sugiere llevar a plenitud lo que falta, ya sea reparación o desarrollo progresivo hacia la madurez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70399, 'spa', 'Equipamiento para el ministerio', 'El Cristo ascendido otorgó dones de liderazgo a la iglesia «para el perfeccionamiento de los santos», capacitando a los creyentes comunes para la obra del ministerio. Este καταρτισμός no es recepción pasiva sino preparación activa. Los líderes no son los únicos ministros, sino capacitadores que llevan a otros a la disposición para servir en el cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70400, 'spa', 'Hacer señas', 'Agitar o mover la mano para pedir silencio o atención antes de hablar. Las cuatro apariciones neotestamentarias están en Hechos, cada una retratando a un orador ante la multitud: Pedro tras su liberación (Hch 12:17), Pablo en Antioquía de Pisidia (Hch 13:16), Alejandro ante la turba efesia (Hch 19:33) y Pablo en Jerusalén (Hch 21:40).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70402, 'spa', 'Preparar, disponer — preparar, alistar o disponer de antemano, frecuentemente co', 'Preparar, disponer — preparar, alistar o disponer de antemano, frecuentemente con el sentido de establecer las condiciones para algo venidero. Es la palabra empleada en la cita sinóptica de Mal 3:1 / Is 40:3, donde un mensajero ''preparará tu camino delante de ti'' (Mt 11:10, Mr 1:2, Lc 7:27). Lucas 1:17 la aplica a Juan el Bautista preparando un pueblo para el Señor. En Hebreos 9:2 describe el tabernáculo siendo ''preparado'' con sus elementos rituales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70403, 'spa', 'Construir, edificar — construir, edificar o erigir una estructura física como un', 'Construir, edificar — construir, edificar o erigir una estructura física como una casa, embarcación o tabernáculo. Se distingue del sentido de ''preparar'' por su enfoque en la construcción material. En Hebreos 3:3-4, el autor razona que ''toda casa es construida (κατασκευάζεται) por alguien, pero el constructor de todas las cosas es Dios'', usando la palabra dos veces en un solo versículo con claro significado constructivo. En 1 Pedro 3:20 describe a Noé construyendo el arca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70410, 'spa', 'Anidar, habitar seguro', 'Establecerse, anidar o alojarse en un lugar, frecuentemente dicho de aves que hallan refugio en las ramas. Las parábolas sinópticas del grano de mostaza (Mt 13:32; Mc 4:32; Lc 13:19) representan aves anidando en el arbusto crecido, evocando Ezequiel 17:23 y Daniel 4:12, donde un gran árbol que cobija aves simboliza un reino que ofrece amparo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70412, 'spa', 'Cubrir con sombra', 'El autor menciona a los querubines de gloria «cubriendo con su sombra el propiciatorio», creando con sus alas un dosel sobre el lugar de la expiación. El participio presente enfatiza su cobertura protectora continua. Esta sombra señala la presencia divina y el punto de encuentro entre Dios y la humanidad, aunque el autor declina profundizar en estos objetos sagrados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70413, 'spa', 'Espiar con hostilidad', 'Pablo caracteriza a los falsos hermanos como espías que se infiltraron «para espiar nuestra libertad», vigilando la práctica cristiana gentil para exigir la circuncisión. El infinitivo de propósito revela que su misión era reconocimiento, no comunión. Como exploradores militares, recopilaban inteligencia para apoyar la campaña del partido de la circuncisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70414, 'spa', 'Espía o explorador', 'La fe de Rahab se demuestra al recibir «a los espías» (los agentes de Josué) en paz, en lugar de entregarlos al rey de Jericó. El sustantivo plural los identifica por su función militar: exploradores que recopilaban inteligencia antes del asalto. Su protección de estos κατάσκοποι en territorio hostil manifestó fe alineada con el Dios de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70415, 'spa', 'Actuar con astucia maliciosa', 'Esteban acusa al faraón de Éxodo 1 de «actuar con astucia» contra Israel: no gobierno severo pero honesto, sino política astuta y maliciosa para destruirlos. El participio caracteriza su trato como explotación sofística con ingenio perverso. Esto incluye los trabajos forzados y la orden de matar a los varones hebreos, estrategias calculadas para eliminar la amenaza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70417, 'spa', 'Porte reverente', 'Las mujeres mayores deben mostrar reverencia ''en su porte'', no solo en actos específicos sino en toda su conducta y comportamiento habitual. El sustantivo capta la totalidad del comportamiento visible, la impresión que se causa mediante la conducta habitual. Esta piedad integral en el porte las capacita para enseñar a las más jóvenes con su ejemplo e instrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70418, 'spa', 'Atuendo decoroso', 'Pablo instruye a las mujeres cristianas a adornarse ''con vestimenta decorosa'', ropa que refleje pudor y dominio propio en lugar de ostentación. El sustantivo puede enfatizar el carácter modesto del atuendo o la manera recatada de llevarlo. En cualquier caso, la preocupación es que la vestimenta no comunique vanidad ni exhibición de riqueza, sino el adorno interior de las buenas obras y la piedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70420, 'spa', 'Sensualidad contra Cristo', 'Pablo advierte que las viudas jóvenes pueden ''volverse sensuales contra Cristo'', cuando sus deseos naturales de matrimonio y familia superan su devoción inicial al ministerio. El verbo sugiere un impulso sensual que las aparta de su compromiso previo. No se condena el matrimonio, sino que se reconoce cómo los anhelos físicos y emocionales descontrolados pueden erosionar el enfoque espiritual, llevando a votos rotos y testimonio desacreditado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70422, 'spa', 'Derribados por juicio', 'La mayoría de la generación del éxodo ''fueron derribados en el desierto'', abatidos por el juicio divino de modo que sus cadáveres quedaron esparcidos por el desierto. El aoristo pasivo enfatiza la acción divina consumada contra ellos. Pablo emplea esta imagen sobrecogedora para advertir a los corintios que el privilegio de la alianza no garantiza inmunidad ante el juicio; la desobediencia acarrea las mismas consecuencias que experimentó el antiguo Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70423, 'spa', 'Arrastrar a la fuerza', 'Jesús advierte que el adversario ''puede arrastrarte'' ante el juez, no escoltarte con cortesía sino llevarte a la fuerza, como quien arresta a un acusado renuente. El subjuntivo indica un peligro potencial si no se logra la reconciliación. Esta elección verbal tan vívida enfatiza la pérdida de autonomía y dignidad cuando el conflicto legal llega a la etapa de ejecución forzosa. Mejor es reconciliarse mientras aún se camina en libertad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70424, 'spa', 'Degollar por orden real', 'El rey que regresa en la parábola de Jesús ordena que sus súbditos rebeldes sean ''degollados delante de mí'', no meramente castigados sino sacrificados como animales. El imperativo aoristo exige ejecución inmediata. Esta conclusión brutal advierte que rechazar la realeza de Jesús trae juicio definitivo, tan severo como el sacrificio de animales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70425, 'spa', 'Sellar para asegurar', 'El rollo en la mano de Dios ''estaba sellado con siete sellos''; el participio perfecto indica que permanecía cerrado y asegurado. Múltiples sellos significaban que nadie podía acceder al contenido sin autorización. Esta seguridad máxima subraya la importancia de lo escrito y la tensión dramática antes de que el Cordero aparezca como el único digno de abrirlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70428, 'spa', 'Mutilación despectiva', 'Pablo llama burlonamente a los partidarios de la circuncisión ''la mutilación'', un juego de palabras despreciativo que reduce su rito a simple corte carnal. El sustantivo κατατομή (cortadura) parodia περιτομή (circuncisión), sugiriendo que su práctica es mutilación sin sentido. Esta retórica niega que la circuncisión física conserve significado teológico tras la venida de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70429, 'spa', 'Descender corriendo apresuradamente', 'El tribuno romano, al escuchar el alboroto, ''corrió hacia abajo'' con tropas desde la fortaleza Antonia hasta el templo donde la multitud golpeaba a Pablo. El aoristo enfatiza la acción inmediata. El verbo capta tanto la velocidad como el movimiento descendente desde la fortaleza elevada hasta los atrios inferiores, detalle que confirma el conocimiento topográfico de Lucas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70430, 'spa', 'Ser vencido, abrumado', 'Ser dominado o abrumado, especialmente por el sueño (en voz pasiva). En Hechos 20:9, Eutico es ''vencido por un sueño profundo'' y cae desde la ventana del tercer piso durante el extenso sermón de Pablo. La forma pasiva enfatiza la naturaleza irresistible y arrolladora de la somnolencia. El español ''siendo vencido'' capta la indefensión propia de la voz pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70432, 'spa', 'Corrupción mental arraigada', 'Los opositores de la verdad son descritos como ''corrompidos de entendimiento''; el participio perfecto indica un estado asentado de depravación mental y moral. No es error momentáneo sino ruina arraigada del intelecto. Como los magos del faraón que resistieron a Moisés, estos maestros se oponen a la verdad apostólica desde una corrupción integral que los descalifica respecto a la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70433, 'spa', 'Besar con fervor', 'Besar con calidez, fervor o de manera repetida: forma intensificada de φιλέω donde el prefijo κατα- transmite plenitud o profundidad emocional. En el griego clásico se distingue del simple φιλεῖν (besar); καταφιλέω implica un beso prolongado, afectuoso o demostrativo. Cada caso en el NT está cargado de emoción: los besos persistentes de la mujer pecadora a los pies de Jesús (Luke 7:38, 45), el abrazo del padre al pródigo (Luke 15:20), el beso traidor de Judas (Matt 26:49; Mark 14:45) y la despedida de los ancianos efesios con Pablo (Acts 20:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70437, 'spa', 'Despreciar, menospreciar', 'Mirar con desprecio desde arriba, considerar como indigno de atención o respeto. El compuesto kata- (''abajo'') + phroneo (''pensar'') crea una imagen vívida de condescendencia mental. En la enseñanza de Jesús aparece en la advertencia sobre despreciar a los niños o los vulnerables (Mt 18:10) y en la imposibilidad de servir a dos señores sin sentir desprecio por uno (Mt 6:24; Lc 16:13). Pablo lo usa para referirse al desdén hacia la iglesia de Dios y la bondad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70446, 'spa', 'Burlador despreciativo', 'Pablo advierte a los judíos de Antioquía de no convertirse en «burladores», aquellos que tratan la obra de Dios con desprecio. El vocativo los señala como posibles candidatos a esta categoría si rechazan el evangelio. El contexto original de Habacuc advertía a quienes se burlaban del juicio anunciado por Dios; Pablo lo reaplica a quienes desestiman la salvación proclamada en Jesús, advirtiendo que el rechazo despectivo acarrea la misma perdición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70448, 'spa', 'Seres del inframundo', 'La aclamación universal de Jesús incluye a «los que están debajo de la tierra» —los καταχθόνιοι—, ya sean los muertos en el Seol/Hades, poderes demoníacos en el abismo o todos los seres del ámbito subterráneo. La asociación clásica del adjetivo con Plutón y el inframundo sugiere que Pablo contempla incluso al reino de los muertos postrándose ante el Cristo exaltado, completando así el alcance cósmico total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70450, 'spa', 'Refrescar, enfriar', 'El hombre rico suplica que Lázaro «refresque mi lengua» con la punta del dedo mojada en agua: el alivio mínimo imaginable para su tormento. El verbo enfatiza el alivio térmico, el toque refrescante del agua sobre tejido atormentado por las llamas. Que incluso este alivio infinitesimal sea negado —por causa del abismo infranqueable— subraya la finalidad del juicio y la irreversibilidad de la gran inversión entre esta vida y la venidera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70451, 'spa', 'Saturado de ídolos', 'Lucas señala que Atenas era κατείδωλος —completamente saturada de ídolos—, no simplemente con algunos templos sino repleta de imágenes de dioses por todas partes. Este adjetivo captura lo que las fuentes antiguas confirman: Atenas tenía más estatuas que habitantes, con templos a incontables deidades bordeando las calles y llenando los espacios públicos. La reacción angustiada de Pablo ante esta saturación idolátrica motivó su confrontación filosófica y su proclamación del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70452, 'spa', 'Enfrente de, frente a', 'Espacial: ''enfrente de, frente a, cara a cara con'' — indica posición física directamente delante de o al otro lado de un punto de referencia. Jesús envía a los discípulos a la aldea ''enfrente'' de ellos (Mt 21:2; Mr 11:2; Lc 19:30); se sienta ''enfrente'' del arca de las ofrendas observando a los que ofrendan (Mr 12:41); y en el Monte de los Olivos está ''enfrente'' del templo (Mr 13:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70453, 'spa', 'Delante de, a la vista de', 'Figurado: ''delante de, a la vista de, en presencia de'' — extiende el sentido espacial de ''estar frente a'' hacia la noción relacional de ser observado o rendir cuentas ante alguien, especialmente Dios. Romanos 4:17 describe la fe de Abraham ''delante de'' (κατέναντι) el Dios que resucita a los muertos; 2 Corintios 2:17 insiste en que Pablo habla ''delante de Dios en Cristo''; y 2 Corintios 12:19 lo reafirma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70454, 'spa', 'Presencia directa de Dios', 'El sentido enfatiza el estar en la presencia directa de Dios, ante su rostro, bajo su mirada. Los tres usos conectan esta preposición con la condición de estar santo o sin mancha ante Dios: la meta de la elección (Efesios 1:4), de la reconciliación (Colosenses 1:22) y de la preservación divina (Judas 24). La forma compuesta (κατά + ἐνώπιον) intensifica la idea de proximidad inmediata, de posicionamiento cara a cara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70456, 'spa', 'Producir, causar o generar un efecto o resultado', 'Producir, causar o generar un efecto o resultado: un uso causativo donde el énfasis recae en el resultado más que en el esfuerzo. Aquí el sujeto (a menudo una fuerza impersonal como la ley, el pecado o el sufrimiento) hace que algo surja. Romanos 4:15 dice que la ley produce ira; Romanos 5:3 declara que la tribulación produce paciencia; Romanos 7:8 y 7:13 describen al pecado produciendo codicia y muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70457, 'spa', 'Llevar a cabo, cumplir o realizar una obra o propósito mediante esfuerzo sosteni', 'Llevar a cabo, cumplir o realizar una obra o propósito mediante esfuerzo sostenido: el uso agentivo y transitivo donde un sujeto activamente ejecuta algo. Pablo emplea este sentido en su angustiado discurso moral (Romanos 7:15, 17, 18, 20), donde el sujeto realiza acciones incluso contra su propia voluntad. Filipenses 2:12 exhorta a obrar la propia salvación con temor y temblor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70471, 'spa', 'Bajar, descender', 'Bajar, descender: moverse hacia abajo desde un lugar elevado a uno inferior, ya sea un descenso geográfico literal o un viaje desde una ciudad elevada a regiones más bajas. En el Evangelio de Lucas, Jesús desciende de entornos montañosos (Lucas 4:31; 9:37). En Hechos, el verbo se vuelve casi formulario para partir de Jerusalén, cuya posición elevada hace que todo viaje desde ella sea un ''descender'' (Hechos 8:5; 9:32; 11:27; 18:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70478, 'spa', 'Devorar o comer literalmente', 'Devorar o comer literalmente: devoramiento físico donde las aves comen la semilla (Mateo 13:4), la fortuna del pródigo es consumida con rameras (Lucas 15:30) y Juan come un rollo (Apocalipsis 10:9). Las traducciones se agrupan en torno al consumo literal: español ''devoraron'', francés ''dévorer'', alemán ''verschlingen''. El énfasis recae en el comer total y a menudo rápido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70479, 'spa', 'Devorar figuradamente o explotar', 'Devorar figuradamente o explotar: explotación figurada y destrucción mutua. Los escribas que devoran las casas de las viudas (Marcos 12:40; Lucas 20:47) y los creyentes gálatas que ''se muerden y devoran unos a otros'' (Gálatas 5:15) ilustran esta metáfora depredadora. El dragón que espera para devorar al hijo recién nacido (Apocalipsis 12:4) extiende la imagen a la persecución satánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70480, 'spa', 'Consumir por fuego o destruir', 'Consumir por fuego o destruir: consumición por fuego o juicio divino. El celo consume a Jesús (Juan 2:17), el fuego devora a los enemigos ante los dos testigos (Apocalipsis 11:5), y en la batalla final el fuego del cielo devora los ejércitos de Gog (Apocalipsis 20:9). La metáfora del comer se mantiene incluso para las llamas, mostrando que la imagen de aniquilación total es culturalmente estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70490, 'spa', 'Guía divina', 'El sentido se centra en la dirección y guía divina, en enderezar el camino. La profecía de Zacarías (Lucas 1:79) visualiza al Mesías guiando a las personas desde las tinieblas y la sombra de muerte hacia el camino de paz. Las oraciones de Pablo (1 Tesalonicenses 3:11; 2 Tesalonicenses 3:5) piden a Dios que allane el camino para el viaje y que dirija los corazones hacia el amor y la perseverancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70491, 'spa', 'Sublevarse en oposición', 'Describe el acto de levantarse colectivamente en oposición u hostilidad contra una persona, como cuando los judíos de Corinto se unieron en su ataque contra Pablo ante el procónsul. La evidencia multilingüe apunta consistentemente a un movimiento adversarial organizado y coordinado, no a un conflicto individual, sino a una acción grupal deliberada contra el mensajero del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70492, 'spa', 'Reprimir, suprimir (contener, reprimir o suprimir a algo o alguien para que no a', 'Reprimir, suprimir (contener, reprimir o suprimir a algo o alguien para que no actúe, avance o se dé a conocer. Romanos 1:18 declara la ira de Dios contra quienes ''reprimen'' la verdad, mientras que 2 Tesalonicenses 2:6-7 habla de un misterioso poder que detiene al hombre de iniquidad. En Lucas 4:42 las multitudes intentaron ''retener'' a Jesús para que no se fuera.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70493, 'spa', 'Poseer, ocupar (poseer, ocupar o tener como propio, ya sea un asiento, una propi', 'Poseer, ocupar (poseer, ocupar o tener como propio, ya sea un asiento, una propiedad o una posición. En 1 Corintios 7:30 Pablo aconseja que los que compran vivan como si no poseyeran. La paradoja de 2 Corintios 6:10, ''no teniendo nada, pero poseyéndolo todo'', juega con este sentido.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70494, 'spa', 'Retener firmemente (aferrarse con firmeza a algo valioso -- fe, tradición, enseñ', 'Retener firmemente (aferrarse con firmeza a algo valioso -- fe, tradición, enseñanza o convicción moral -- y negarse a soltarlo. En Lucas 8:15 la buena tierra representa a quienes oyen la palabra y ''la retienen'' en un corazón honesto, y en 1 Corintios 11:2 Pablo elogia a la iglesia por retener las tradiciones que les entregó.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70497, 'spa', 'Estar retenido, estar atado (en voz pasiva, estar sujeto, atado o cautivo por un', 'Estar retenido, estar atado (en voz pasiva, estar sujeto, atado o cautivo por una aflicción, obligación o condición espiritual. Juan 5:4 describe a los ''retenidos'' por diversas enfermedades junto al estanque de Betesda, y Romanos 7:6 habla de haber sido liberados de la ley que antes ''nos retenía''.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70500, 'spa', 'Dirigirse hacia, poner rumbo (término técnico náutico que significa gobernar o m', 'Dirigirse hacia, poner rumbo (término técnico náutico que significa gobernar o mantener el rumbo hacia un destino. En Hechos 27:40 los marineros cortaron las anclas, izaron la vela de proa y ''se dirigieron'' hacia la playa. La imagen subyacente permanece coherente: sujetar firmemente el barco en su curso.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70507, 'spa', 'Acusación activa', 'Acusación activa: acusar formalmente, presentar cargos o denunciar a alguien ante un tribunal o autoridad. Este sentido dominante (20 apariciones) abarca todas las formas en voz activa. Los fariseos buscan motivos para acusar a Jesús (Mateo 12:10, Marcos 3:2, Lucas 6:7), los principales sacerdotes lo acusan ante Pilato (Marcos 15:3-4) y los judíos presentan cargos contra Pablo (Hechos 24:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70511, 'spa', 'Acusación pasiva', 'Acusación pasiva: ser acusado, tener cargos presentados en contra, estar bajo acusación formal. Jesús permanece en silencio mientras es acusado por los principales sacerdotes (Mateo 27:12); el tribuno romano busca conocer los cargos contra Pablo (Hechos 22:30); Festo insiste en que el acusado debe enfrentar a sus acusadores (Hechos 25:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70522, 'spa', 'Acusación formal', 'El sentido es el de una acusación o cargo formal, particularmente en contextos legales o cuasi-legales. La pregunta de Pilato exige un cargo específico, pues el derecho romano requería acusaciones claras. El pasaje de Timoteo establece salvaguardas procesales para acusar a líderes eclesiales, protegiendo contra la calumnia sin impedir la disciplina legítima. En Tito se trata de la reputación irreprochable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70523, 'spa', 'Acusador', 'Acusador o fiscal: quien presenta formalmente cargos o habla en contra de otro en un contexto judicial. El término pertenece al vocabulario forense del derecho griego. En Juan 8:10, Jesús pregunta a la mujer si queda algún acusador para condenarla. Hechos lo usa repetidamente en contextos legales romanos: Lisias envía a los acusadores de Pablo ante Félix (Hch 23:30, 35), y Apocalipsis 12:10 designa a Satanás como acusador cósmico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70526, 'spa', 'Abatimiento y pesadumbre', 'Se refiere al estado emocional y físico de abatimiento, manifestado en la mirada baja y el semblante entristecido. En el llamado de Santiago al arrepentimiento, representa la gravedad apropiada de quien reconoce su condición espiritual, oponiéndose a la alegría superficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70527, 'spa', 'Informar, dar noticia', 'Informar, comunicar o transmitir noticias — en voz pasiva, ser enterado de algo. Este sentido aparece exclusivamente en Hechos 21:21 y 21:24, donde los creyentes judíos de Jerusalén ''han sido informados'' de que Pablo enseña a los judíos entre los gentiles a abandonar a Moisés. El español pasa de ''instruido'' (sentido 1) a ''han sido informados'', reflejando claramente el cambio semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70528, 'spa', 'Instruir, enseñar la fe', 'Dar instrucción oral y sistemática en la verdad o doctrina religiosa — el sentido catequético clásico. Es el uso dominante en el NT (6 de 8 apariciones), visible en Lucas 1:4, donde Teófilo fue ''instruido'' en la fe, en Hechos 18:25, donde Apolos había sido ''enseñado'' en el camino del Señor, y en Gálatas 6:6, donde el ''catequizado'' comparte con su catequista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70533, 'spa', 'Corroerse u oxidarse', 'Describe el proceso pasivo de enmohecerse o deteriorarse, especialmente tratándose de metales preciosos. En la advertencia de Santiago a los ricos, esta corrosión funciona como señal de deterioro literal y como testimonio moral, mostrando cómo la riqueza sin uso se degrada y testifica contra quienes la acumulan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70534, 'spa', 'Prevalecer con fuerza', 'El sentido es el de poseer fuerza o poder superior, prevalecer en un conflicto o contienda. Mateo 16:18 promete que ni los poderes de la muerte («puertas del Hades») podrán vencer a la iglesia de Cristo. Lucas 21:36 se refiere a que los creyentes tengan la fuerza necesaria para escapar de la tribulación. En Lucas 23:23, «sus voces prevalecieron» describe cómo la insistencia de la multitud venció la resistencia de Pilato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70535, 'spa', 'Habitar, morar en un lugar', 'El sentido principal: habitar o morar en un lugar como residente establecido. Se usa extensamente en Hechos para las poblaciones de ciudades y regiones (Hch 1:19; 2:5; 4:16) y en Apocalipsis para ''los que habitan en la tierra'' como frase recurrente (Ap 3:10; 6:10). Mateo 23:21 lo extiende a Dios que habita en el templo. Efesios 3:17 lo aplica a Cristo habitando en los corazones de los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70539, 'spa', 'Establecerse, fijar residencia', 'Sentido ingresivo o puntual: establecerse, fijar residencia, asentarse en un lugar nuevo. La Sagrada Familia estableciendose en Nazaret (Mt 2:23) y el viaje de Abraham a Canaan (Hch 7:2-4) ilustran el acto de comenzar a habitar. Hechos 17:26 lo usa para Dios determinando donde se establecerian las naciones, conectando la providencia divina con la geografia humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70545, 'spa', 'Hacer habitar, establecer', 'Un uso causativo o transitivo poco frecuente: hacer habitar, establecer a alguien en un lugar. Santiago 4:5 contiene la unica instancia neotestamentaria, donde Dios ''hizo habitar'' al Espiritu en los creyentes. El pasaje es exegeticamente debatido, pero la fuerza causativa de κατοικέω aqui es clara por la gramatica y el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70552, 'spa', 'Morada o residencia', 'Indica un lugar de habitación o residencia donde alguien se establece. En el caso del endemoniado gadareno, esta morada entre los sepulcros resalta su aislamiento y la gravedad de su aflicción, pues vivía donde descansan los muertos en vez de habitar entre la comunidad de los vivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70554, 'spa', 'Lugar de asentamiento', 'Designa lugares de habitación en el sentido amplio de regiones donde los pueblos se asientan. En el discurso de Pablo en el Areópago, este término enfatiza el ordenamiento soberano de Dios sobre la geografía y la historia humanas, determinando no solo a los individuos sino dónde pueblos enteros establecen sus moradas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70555, 'spa', 'Contemplar como en espejo', 'Describe el acto de mirar algo como en un espejo, involucrando tanto reflexión como contemplación. En la enseñanza de Pablo sobre la transformación, sugiere que los creyentes o bien reflejan la gloria de Cristo hacia otros, o bien la contemplan como en un reflejo nítido, experimentando una transformación progresiva mediante la visión espiritual sostenida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70556, 'spa', 'Abajo, debajo, bajo — adverbio espacial que significa ''abajo, debajo, bajo'', ind', 'Abajo, debajo, bajo — adverbio espacial que significa ''abajo, debajo, bajo'', indicando ya sea movimiento descendente o posición estática inferior a lo largo de un eje vertical. Cubre usos direccionales — arrojarse abajo (Mt 4:6; Lc 4:9), el velo rasgado hasta abajo (Mt 27:51; Mr 15:38) — y usos locativos — Pedro abajo en el patio (Mr 14:66), ser ''de abajo'' versus ''de arriba'' en la teología joánica (Jn 8:23). El uso comparativo de umbral aparece en Mt 2:16 con ''de dos años para abajo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70558, 'spa', 'Posición espacial inferior', 'Indica una posición espacial más baja en comparación con algo superior. En el pasaje de Efesios, esto genera una cosmología vertical donde el descenso de Cristo a la tierra (o a la muerte) contrasta deliberadamente con su posterior ascensión por encima de todos los cielos, subrayando el alcance completo de su movimiento redentor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70560, 'spa', 'Abrasar con calor', 'Quemar o abrasar con calor intenso, generalmente procedente del sol. En las parábolas sinópticas del sembrador (Mt 13:6; Mc 4:6), las plantas en suelo pedregoso son abrasadas al salir el sol, ilustrando cómo la persecución destruye la fe superficial. En Apocalipsis 16:8-9, el mismo verbo se eleva a juicio escatológico cuando el sol recibe poder para abrasar a la humanidad con fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70561, 'spa', 'Quema destructiva', 'Designa el acto o estado de arder, particularmente como forma de destrucción o eliminación. En la advertencia de Hebreos, esta quema representa el juicio final de Dios sobre una vida espiritual persistentemente improductiva, usando la imagen agrícola de limpiar el crecimiento inútil de la tierra mediante el fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70563, 'spa', 'Calor abrasador', 'El calor ardiente y marchitante del día, especialmente el del viento siroco. Las tres apariciones neotestamentarias emplean esta palabra para describir un calor intenso: los jornaleros de la viña en Mateo 20:12 lo soportaron durante su jornada, Lucas 12:55 lo menciona como pronóstico meteorológico cuando sopla el viento del sur, y Santiago 1:11 lo usa metafóricamente para el sol abrasador que marchita las plantas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70564, 'spa', 'Conciencia cauterizada', 'Describe el estado pasivo de ser cauterizado, especialmente de la conciencia que se vuelve insensible por el compromiso moral repetido. Pablo advierte sobre falsos maestros cuyo engaño constante ha cicatrizado su percepción moral, dejándolos incapaces de reconocer la verdad o sentir convicción, como carne cauterizada que ha perdido toda sensación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70565, 'spa', 'Jactarse, gloriarse', 'Jactarse, gloriarse o enorgullecerse de algo, ya sea positiva o negativamente. Pablo domina el uso, empleandolo para la jactancia ilegitima en la ley (Ro 2:17, 23), la jactancia legitima en la esperanza de gloria (Ro 5:2), la jactancia paradojica en el sufrimiento (Ro 5:3) y el gloriarse exultante en Dios por medio de Cristo (Ro 5:11). El espanol distingue ''jactarse'' (vanagloria) de ''gloriarse'' (exaltacion positiva).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70580, 'spa', 'Ser quemado (variante textual)', 'Una lectura variante en 1 Co 13:3 donde algunos manuscritos tienen καυθήσομαι (''sere quemado'') en lugar de καυχήσωμαι (''me jacte''). La confusion surge de la similitud visual entre χ y θ en la escritura uncial. El espanol ''sea quemado'' refleja esta variante, que altera significativamente el sentido: del orgullo vacio al martirio sacrificial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70587, 'spa', 'Motivo de jactancia, base para gloriarse — el objeto, fundamento o asunto de la ', 'Motivo de jactancia, base para gloriarse — el objeto, fundamento o asunto de la jactancia, la cosa concreta en la cual uno se enorgullece o a la que señala como base de su confianza. Abraham podría tener un motivo de jactancia ante los hombres pero no ante Dios (Ro 4:2). El motivo de gloria de Pablo es predicar el evangelio sin cobrar (1 Co 9:15-16), y sus iglesias son su motivo de gloria en el retorno de Cristo (2 Co 1:14; Fil 1:26; 2:16). Los creyentes deben examinar su propia obra para que su motivo de gloria se sostenga por sus propios méritos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70592, 'spa', 'Jactancia, acto de gloriarse — El acto, ejercicio o proceso de jactarse, gloriar', 'Jactancia, acto de gloriarse — El acto, ejercicio o proceso de jactarse, gloriarse o exultar: la actividad de enorgullecerse de algo. Pablo declara que la jactancia queda excluida por el principio de la fe (Rom 3:27) y que su propia jactancia en Cristo Jesus se refiere a las cosas de Dios (Rom 15:17). Su jactancia respecto a los corintios queda vindicada (2 Cor 7:4, 14; 8:24), asi como su jactancia en la santa sinceridad de conciencia (2 Cor 1:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70596, 'spa', 'Valle de Cedrón', 'Se refiere al valle de Cedrón, el barranco que Jesús cruzó la noche de su traición. Este marcador geográfico tiene resonancia veterotestamentaria: David huyó por él de Absalón, y reyes posteriores purificaron Jerusalén arrojando ídolos en este cauce, convirtiéndolo en frontera simbólica entre la ciudad y el lugar de oración y prueba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70597, 'spa', 'De objetos colocados, puestos o que yacen físicamente en un lugar', 'De objetos colocados, puestos o que yacen físicamente en un lugar. Las tinajas de agua están puestas allí (Juan 2:6), los lienzos yacen en el sepulcro (Juan 20:5-7) y los bienes están almacenados para uso futuro (Lucas 12:19). Las narrativas del sepulcro son especialmente vívidas, distinguiendo los lienzos tendidos del sudario enrollado aparte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70598, 'spa', 'De personas acostadas, reclinadas o puestas en algún lugar', 'De personas acostadas, reclinadas o puestas en algún lugar. El niño Jesús está acostado en un pesebre (Lucas 2:12, 16), el ángel anuncia que no está aquí donde su cuerpo había yacido (Mateo 28:6) y el sepulcro nuevo de José es donde fue puesto el cuerpo (Lucas 23:53).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70599, 'spa', 'De algo establecido, puesto o fijado como principio o realidad', 'De algo establecido, puesto o fijado como principio o realidad. El hacha ya está puesta a la raíz de los árboles (Mateo 3:10; Lucas 3:9), un velo yace sobre el corazón cuando se lee a Moisés (2 Corintios 3:15) y la ley está puesta para los transgresores (1 Timoteo 1:9). Transmite algo colocado con autoridad vinculante o inevitabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70602, 'spa', 'En sentido figurado, estar puesto, designado o destinado para un propósito parti', 'En sentido figurado, estar puesto, designado o destinado para un propósito particular. Pablo dice que está puesto para la defensa del evangelio (Filipenses 1:16) y les dice a los tesalonicenses que estamos puestos para las aflicciones (1 Tesalonicenses 3:3). Extiende la imagen concreta de colocación física al ámbito del designio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70604, 'spa', 'De una ciudad, lugar o entidad que se encuentra situada geográficamente', 'De una ciudad, lugar o entidad que se encuentra situada geográficamente. Una ciudad asentada sobre un monte no se puede esconder (Mateo 5:14) y la nueva Jerusalén yace en forma cuadrada (Apocalipsis 21:16). El mundo entero yace en el poder del maligno (1 Juan 5:19), extendiendo la metáfora espacial a una esfera cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70613, 'spa', 'Vendas funerarias', 'Designa las tiras de tela de lino usadas para envolver un cadáver en la práctica funeraria judía del siglo primero. Cuando Lázaro aparece aún envuelto en estas vendas mortuorias, esto ofrece prueba visual de la resurrección y requiere que otros lo desaten, imagen vívida de la liberación de la muerte que necesita la participación comunitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70614, 'spa', 'Esquilar o rapar', 'Esquilar la lana de las ovejas o cortar el cabello humano, a menudo en relación con votos religiosos o como acto culturalmente significativo. Abarca desde la imagen agrícola del esquileo en Hechos 8:32 (citando Is 53:7, el Siervo mudo ante su trasquilador) hasta el acto ritual de Pablo rapándose en Cencrea por un voto (Hch 18:18). En 1 Corintios 11:6, Pablo lo usa para argumentar sobre la deshonra de ir rapada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70615, 'spa', 'Voz de mando', 'Designa un mandato fuerte y autoritativo que desencadena una acción decisiva. En la visión escatológica de Pablo, este grito de mando —ya sea de Cristo, de un arcángel o de Dios mismo— inaugura la resurrección, de manera análoga a como la orden de un comandante pone en marcha a un ejército o la señal del cómitre sincroniza a los remeros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70616, 'spa', 'Dar una orden o mandato con autoridad, dicho por personas en posiciones de poder', 'Dar una orden o mandato con autoridad, dicho por personas en posiciones de poder reconocido: reyes, gobernadores, oficiales militares y señores. Jesús ordena a las multitudes sentarse y a Pedro venir a él sobre el agua (Mateo 14:19, 28; 15:35), Pilato ordena entregar el cuerpo de Jesús (Mateo 27:58) y en Hechos el verbo se vuelve casi formulario para procedimientos judiciales y militares: el tribuno ordena la detención de Pablo (Hechos 21:33-34; 22:24) y Festo ordena que Pablo sea custodiado (Hechos 25:6, 21, 23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70623, 'spa', 'Vanagloria', 'Designa la búsqueda de reconocimiento vacío u honor sin valor, impulsada por el orgullo en lugar de la verdad. En el llamado paulino a la humildad cristológica, representa la autopromoción competitiva que destruye la comunidad, en agudo contraste con el ejemplo de Cristo, quien no se aferró a su gloria sino que tomó forma de siervo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70624, 'spa', 'Vanaglorioso', 'Describe a quienes se caracterizan por la vanidad y el orgullo hueco, buscando activamente un honor sin valor. Pablo advierte que tal vanagloria produce inevitablemente provocación y envidia, generando dinámicas comunitarias tóxicas donde las personas compiten por reconocimiento en vez de celebrar mutuamente los dones y caminar al paso del Espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70625, 'spa', 'Vano, sin resultado (sin propósito, efecto ni sustancia genuina, usado en sentid', 'Vano, sin resultado (sin propósito, efecto ni sustancia genuina, usado en sentido figurado de esfuerzos, palabras o afirmaciones que no logran nada. Pablo advierte que sin la resurrección, tanto la predicación como la fe son ''vanas'' (1 Co 15:14). En Efesios 5:6 las palabras vacías son vehículo de engaño.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70627, 'spa', 'Vacío, con las manos vacías (carente físicamente de contenido o posesiones; desp', 'Vacío, con las manos vacías (carente físicamente de contenido o posesiones; despedido sin nada en las manos. Los labradores en la parábola de Jesús golpearon al siervo del dueño y lo despidieron con las manos vacías (Mc 12:3; Lc 20:10-11). María canta que Dios despidió a los ricos ''vacíos'' (Lc 1:53). Aquí el sentido literal de un recipiente sin llenar o una palma abierta subyace a la imagen.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70629, 'spa', 'Insensato, necio (usado como epíteto personal que significa insensato o falto de', 'Insensato, necio (usado como epíteto personal que significa insensato o falto de entendimiento espiritual. Santiago 2:20 se dirige directamente a tal persona: ''¡Oh hombre vacío!, ¿quieres prueba de que la fe sin obras es inútil?'' El concepto griego de una persona ''vacía'' carente de νοῦς adquiere un filo retórico agudo en este uso único del Nuevo Testamento.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70634, 'spa', 'Vaciar o anular', 'Vaciar, dejar sin contenido, fuerza o significado. La imagen concreta de vaciar un recipiente se extiende metafóricamente en todo el NT. En Fil 2:7, Cristo «se vació a sí mismo» (la kénosis), no de su divinidad sino de sus prerrogativas divinas, tomando forma de siervo. En Ro 4:14 y 1 Co 1:17, la fe y la cruz son «vaciadas» o anuladas si los sistemas humanos suplantan la gracia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70635, 'spa', 'Aguijón o punta', 'Punta aguda usada como aguijón, aguijón venenoso o instrumento punzante. El término abarca desde la vara del pastor para arrear ganado hasta el aguijón mortal de la muerte. En Hch 9:5 y 26:14, los «aguijones» representan la dirección divina que Pablo resiste, el proverbial κέντρα λακτίζειν. En 1 Co 15:55-56 el «aguijón» de la muerte se personifica y se identifica con el pecado, vencido por la resurrección de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70636, 'spa', 'Centurión romano', 'Un centurión romano, el oficial militar al mando de una centuria (aproximadamente cien soldados). Las tres apariciones en Marcos 15:39-45 se refieren al mismo individuo: el centurión que supervisó la crucifixión de Jesús y que, al presenciar su muerte, declaró: «Verdaderamente este hombre era Hijo de Dios». Esta confesión de un oficial militar gentil posee una profunda significación teológica en la narrativa de Marcos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70637, 'spa', 'En vano', 'Indica una acción o discurso vacío, sin propósito o sin resultado. En la referencia de Santiago a lo que dice la Escritura, el punto es que la palabra de Dios nunca habla ociosamente ni deja de cumplir su propósito: cada declaración divina tiene peso y produce su efecto previsto, a diferencia de las palabras humanas que pueden carecer de contenido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70639, 'spa', 'Alfarero', 'Artesano que moldea barro para formar vasijas. Mateo 27:7, 10 hace referencia al «campo del alfarero», terreno comprado con las treinta monedas devueltas por Judas en cumplimiento de la profecía. Romanos 9:21 emplea al alfarero como metáfora: así como el alfarero tiene autoridad sobre el barro para hacer vasijas diferentes, Dios tiene soberanía sobre su creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70640, 'spa', 'De barro', 'Designa objetos hechos de arcilla o alfarería, subrayando su fragilidad y facilidad de rotura. En la promesa de Apocalipsis a los vencedores, la imagen de vasos de barro quebrados representa la destrucción total de la oposición rebelde al gobierno de Cristo: la cerámica se quiebra irremediablemente al ser golpeada con autoridad de hierro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70642, 'spa', 'Tejas de barro', 'Se refiere a las tejas de arcilla que formaban la cubierta de los tejados, las cuales podían retirarse y reponerse. El relato de los amigos que desmontan parte del techo para llegar hasta Jesús ilustra tanto la arquitectura doméstica de la época —casas con techos planos accesibles— como una fe extraordinaria que no permite que ningún obstáculo impida acercar al enfermo al sanador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70643, 'spa', 'Mezclar líquidos', 'Mezclar o combinar líquidos entre sí. Las tres apariciones bíblicas se encuentran en escenas de juicio del Apocalipsis. En 14:10, el vino de la ira de Dios se describe como «mezclado puro», expresión paradójica que subraya su máxima intensidad. Apocalipsis 18:6 (dos veces) ordena que Babilonia reciba doble porción «en la copa que ella mezcló», empleando la imagen de justicia retributiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70644, 'spa', 'Cuerno — Un cuerno literal de animal o proyeccion en forma de cuerno, incluyendo', 'Cuerno — Un cuerno literal de animal o proyeccion en forma de cuerno, incluyendo los cuernos del altar de oro en el templo celestial (Ap 9:13), que evoca el altar de incienso de cuatro cuernos de Exodo 30:2. El referente fisico subyace a todas las extensiones metaforicas, desde el poder real hasta la salvacion divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70646, 'spa', 'Vainas de algarrobo', 'Designa las vainas del algarrobo, utilizadas habitualmente como alimento para cerdos y consideradas comida de extrema pobreza. El deseo del pródigo de comer estas vainas marca el punto más bajo de su camino: un hijo judío reducido a envidiar la comida de los puercos, incapaz siquiera de conseguir este alimento mísero, lo cual lo empuja hacia el arrepentimiento y el retorno al padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70647, 'spa', 'Ganar personas (ganar personas mediante la persuasión, la corrección o el ejempl', 'Ganar personas (ganar personas mediante la persuasión, la corrección o el ejemplo piadoso. El gran manifiesto misionero de Pablo en 1 Corintios 9:19-22 usa κερδαίνω cinco veces para ganar a judíos, gentiles y débiles para la fe. Jesús lo emplea en Mateo 18:15 para la corrección fraterna: ''has ganado a tu hermano''.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70648, 'spa', 'Ganar beneficio económico (obtener ganancia o beneficio económico, especialmente', 'Ganar beneficio económico (obtener ganancia o beneficio económico, especialmente mediante el comercio o la inversión. La parábola de los talentos (Mt 25:16-22) usa este verbo tres veces para los siervos que negociaron y ''ganaron'' talentos adicionales. Este es el sentido más literal y comercial de la palabra.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70652, 'spa', 'Obtener algo valioso (obtener o alcanzar algo de gran valor, a menudo abstracto ', 'Obtener algo valioso (obtener o alcanzar algo de gran valor, a menudo abstracto o espiritual. Jesús plantea la pregunta existencial: ''¿De qué le sirve a una persona ganar el mundo entero y perder su alma?'' (Mt 16:26; Mc 8:36). Pablo invierte los valores mundanos por completo, considerando todo como basura ''a fin de ganar a Cristo'' (Fil 3:8).)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70653, 'spa', 'Evitar una pérdida (ganar en el sentido de evitar o ser librado de una pérdida o', 'Evitar una pérdida (ganar en el sentido de evitar o ser librado de una pérdida o daño. En Hechos 27:21, Pablo dice a los marineros azotados por la tormenta que debieron haberle escuchado y así ''haber evitado este daño y pérdida''. Es un uso idiomático singular donde ''ganar'' paradójicamente significa ''no sufrir''.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70658, 'spa', 'Ganancia o provecho', 'Ganancia, provecho o ventaja. Filipenses 1:21 la emplea de modo sorprendente: Pablo considera la muerte «ganancia» porque lo une con Cristo. En Filipenses 3:7, lo que antes contaba como ganancias ahora lo considera pérdida por amor a Cristo. Tito 1:11 habla negativamente de quienes enseñan doctrina falsa «por ganancias deshonestas», mostrando la ambigüedad moral del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70659, 'spa', 'Monedas de cobre', 'Se refiere a monedas o calderilla, particularmente moneda de cobre empleada en transacciones cotidianas. Cuando Jesús esparce estas monedas durante la purificación del templo, la imagen evoca tanto el juicio sobre el comercio corrupto como una disrupción dramática: el dinero rodando por los atrios mientras los comerciantes se apresuran, con su negocio literalmente derribado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70660, 'spa', 'Cambista de moneda', 'Designa a los cambistas profesionales que convertían moneda extranjera en moneda aceptable para el templo. Aunque prestaban un servicio necesario a los peregrinos que portaban dinero romano o griego, su presencia en los atrios del templo —y posiblemente sus tasas de cambio abusivas— representaba la mercantilización del culto que Jesús confrontó con fuerza profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70662, 'spa', 'Golpear en la cabeza', 'Describe el acto de golpear violentamente a alguien en la cabeza. En la parábola de Jesús, esta agresión contra el representante del dueño de la viña ilustra la resistencia creciente de Israel hacia los mensajeros de Dios, una violencia que culminará con la muerte del hijo amado, simbolizando el rechazo definitivo de la humanidad a la autoridad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70663, 'spa', 'cabeza (literal y figurado)', 'La cabeza, tanto la parte anatómica literal del cuerpo (Mt 5:36; 6:17; 14:8 — la cabeza cercenada del Bautista) como el sentido metafórico de autoridad o preeminencia (1 Co 11:3; Ef 1:22; Col 1:18 — Cristo como cabeza de la iglesia). El español ''cabeza'' abarca ambos sentidos, físico y figurado, reflejando fielmente el griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70666, 'spa', 'Rollo o pergamino', 'Designa un libro enrollado o pergamino, la forma habitual de los documentos escritos en la antigüedad. En la cita de Hebreos, este ''rollo del libro'' representa el testimonio escritural acumulado que señala hacia el Mesías, el cual Cristo reclama como su propio guión divino: él viene a cumplir lo que fue escrito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70667, 'spa', 'Tributo imperial', 'Impuesto personal o tributo exigido por la autoridad romana a las poblaciones conquistadas, recaudado por individuo y no sobre bienes o propiedades. Las cuatro apariciones en el NT se agrupan en torno a la controversia sobre pagar tributo al César (Mt 17:25; 22:17, 19; Mc 12:14), subrayando la dimensión política de someterse al dominio imperial mediante el cumplimiento fiscal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70668, 'spa', 'Huerto, jardín cercado', 'Un jardín, huerto o terreno cultivado y cercado. En el NT la palabra combina sentido práctico y peso simbólico. Juan 18:1 y 18:26 sitúan el arresto de Jesús en un huerto al otro lado del valle del Cedrón, mientras que Juan 19:41 ubica el sitio de la crucifixión junto a un huerto con una tumba nueva, evocando la pérdida y restauración del Edén. Lucas 13:19 emplea el término en la parábola del grano de mostaza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70669, 'spa', 'Jardinero', 'Designa a quien cultiva y cuida un jardín, responsable de su mantenimiento. La suposición de María de que Jesús es el jardinero del cementerio añade una conmovedora ironía al relato de la resurrección: ella se encuentra ante el creador del Edén y fuente de toda vida, pero solo percibe a un humilde servidor que atiende un terreno funerario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70670, 'spa', 'Proclamación, predicación', 'El acto o contenido de la proclamación pública, especialmente la predicación kerigmática del evangelio. Κήρυγμα deriva de la tradición del heraldo (κῆρυξ) y conlleva connotaciones de anuncio oficial y autoritativo. En el NT se refiere tanto al mensaje proclamado (Ro 16:25, ''mi evangelio y la proclamación de Jesucristo''; Tit 1:3, la palabra confiada mediante la predicación) como al acto mismo de proclamar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70674, 'spa', 'Heraldo o pregonero', 'Heraldo o proclamador público. Pablo se describe como «heraldo y apóstol» en 1 Timoteo 2:7 y 2 Timoteo 1:11, subrayando su función de anunciar públicamente el mensaje del evangelio. 2 Pedro 2:5 llama a Noé «pregonero de justicia», destacando su papel como portavoz de Dios que advertía al mundo antediluviano. El término enfatiza la proclamación fiel del mensaje ajeno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70675, 'spa', 'proclamar, predicar, pregonar', 'Proclamar o pregonar públicamente un mensaje con autoridad oficial, abarcando tanto la predicación de arrepentimiento de Juan el Bautista en el desierto (Mt 3:1) como la proclamación del reino por parte de Jesús (Mt 4:17, 23). El vínculo etimológico con κῆρυξ (''heraldo'') subraya que no se trata de conversación casual sino de anuncio autoritativo destinado a ser ampliamente escuchado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70704, 'spa', 'Gran criatura marina', 'Denota cualquier criatura o monstruo marino de gran tamaño, específicamente el que se tragó a Jonás. Jesús emplea este episodio como señal profética: así como Jonás pasó tres días en el vientre de la criatura antes de salir con vida, el Hijo del Hombre pasaría tres días en la tierra antes de resucitar, vinculando profeta y Mesías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70705, 'spa', 'Cefas (nombre propio)', 'El nombre arameo Cefas (del arameo kepha, ''roca''), dado por Jesús a Simón Pedro y usado predominantemente en la correspondencia paulina. Juan 1:42 registra el momento del nombramiento y ofrece la traducción griega (Πέτρος). La preferencia constante de Pablo por ''Cefas'' (1 Co 1:12; 3:22; 9:5; 15:5; Gá 1:18; 2:9,11,14) refleja su vínculo con la comunidad de Jerusalén de habla aramea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70709, 'spa', 'Arca', 'Recipiente grande con forma de caja, que abarca tanto el arca de Noé —la gran embarcación construida por mandato divino para preservar la vida durante el diluvio (Matt 24:38; Luke 17:27; Heb 11:7; 1 Pet 3:20)— como el Arca del Pacto, el cofre sagrado revestido de oro que contenía las tablas, la vasija de maná y la vara de Aarón (Heb 9:4). Aunque en el griego clásico κιβωτός designa cualquier cofre o arca, en el NT se limita exclusivamente a estos dos referentes teológicos.');